* { box-sizing: border-box; }
:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172b35;
  background: #172b35;
  font-size: 16px;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px 20px;
  display: grid;
  place-items: center;
  background-color: #172b35;
  background-image: radial-gradient(#38515a 1.5px, transparent 1.5px);
  background-size: 18px 18px;
}
.game-card {
  width: min(100%, 650px);
  padding: clamp(20px, 5vw, 38px);
  background: #fffaf0;
  border: 4px solid #172b35;
  box-shadow: 8px 8px 0 #d78454;
}
.game-header { text-align: center; margin-bottom: 24px; }
.eyebrow, .status-label { color: #a95236; font-size: .8rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }
.eyebrow { margin: 0 0 8px; }
h1 { margin: 0; font-size: clamp(1.65rem, 6vw, 2.5rem); line-height: 1.1; letter-spacing: -.045em; }
h1 span { color: #d78454; }
.intro { margin: 10px 0 0; color: #4d6267; line-height: 1.5; }
.board-wrap { max-width: 500px; margin: 0 auto; }
.board {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 5px;
  padding: 7px;
  background: #172b35;
  border: 3px solid #172b35;
}
.cell {
  position: relative;
  aspect-ratio: 1;
  min-width: 0;
  display: grid;
  place-items: start;
  padding: 5px;
  overflow: hidden;
  background: #e7d9b9;
  border: 2px solid #c3b58f;
  font-size: clamp(.68rem, 2.4vw, .95rem);
  font-weight: 800;
}
.cell:nth-child(4n + 2), .cell:nth-child(4n + 3) { background: #f2e9d3; }
.cell.goal { background: #e4ad57; border-color: #a66c2f; }
.cell.start { background: #b7d0b1; border-color: #719578; }
.cell-number { position: relative; z-index: 1; }
.cell-mark { position: absolute; right: 4px; bottom: 2px; font-size: clamp(.8rem, 3.5vw, 1.25rem); line-height: 1; }
.cell-mark.ladder { color: #407b61; }
.cell-mark.snake { color: #a95236; }
.token {
  position: absolute;
  z-index: 2;
  right: 4px;
  top: 4px;
  width: 12px;
  height: 12px;
  background: #d78454;
  border: 2px solid #172b35;
  box-shadow: 3px 3px 0 #172b35;
}
.legend { display: flex; justify-content: center; flex-wrap: wrap; gap: 18px; padding: 12px 0 0; color: #4d6267; font-size: .9rem; }
.legend span { display: inline-flex; align-items: center; gap: 7px; }
.legend i { width: 13px; height: 13px; display: inline-block; border: 2px solid #172b35; }
.key-ladder { background: #78a78a; }
.key-snake { background: #d78454; border-radius: 50%; }
.key-player { background: #d78454; box-shadow: 2px 2px 0 #172b35; }
.controls { max-width: 500px; margin: 22px auto 0; display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.status-card { display: grid; grid-template-columns: auto 1fr; column-gap: 10px; align-items: center; }
.status-label { grid-column: 1 / -1; font-size: .72rem; }
.square-number { font-size: 2.5rem; line-height: 1.05; }
.message { color: #4d6267; font-size: .95rem; }
.roll-area { display: flex; align-items: center; gap: 10px; }
.die { width: 42px; height: 42px; display: grid; place-items: center; flex: 0 0 auto; background: #fff; border: 3px solid #172b35; box-shadow: 3px 3px 0 #d78454; font-size: 1.25rem; font-weight: 900; }
button { min-height: 48px; padding: 0 16px; border: 3px solid #172b35; background: #d78454; color: #172b35; font: inherit; font-weight: 850; cursor: pointer; box-shadow: 4px 4px 0 #172b35; transition: transform .12s, box-shadow .12s, background-color .12s; }
button:hover { background: #e69a68; transform: translate(-1px, -1px); box-shadow: 5px 5px 0 #172b35; }
button:focus-visible { outline: 3px solid #407b61; outline-offset: 4px; }
button:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 #172b35; }
button:disabled { cursor: default; opacity: .7; }
.rule-note { margin: 18px 0 0; text-align: center; color: #687a78; font-size: .85rem; }
footer { margin-top: 17px; color: #d3d9d0; text-align: center; font-size: .9rem; }
@media (max-width: 430px) {
  body { padding: 16px 10px; }
  .game-card { padding: 20px 14px; box-shadow: 5px 5px 0 #d78454; }
  .board { gap: 3px; padding: 4px; }
  .cell { padding: 3px; border-width: 1px; }
  .controls { align-items: flex-start; flex-direction: column; }
  .roll-area { width: 100%; }
  button { flex: 1; }
}

const ladders = new Map([[3, 11], [8, 17], [20, 29]]);
const snakes = new Map([[14, 5], [24, 16], [28, 9]]);
const board = document.querySelector('#board');
const squareDisplay = document.querySelector('#square');
const message = document.querySelector('#message');
const dieDisplay = document.querySelector('#die');
const rollButton = document.querySelector('#roll');
let position = 1;
let finished = false;

function renderBoard() {
  board.replaceChildren();
  for (let row = 0; row < 5; row += 1) {
    const ascending = row % 2 === 0;
    const values = Array.from({ length: 6 }, (_, col) => {
      const offset = row * 6 + col;
      return ascending ? offset + 1 : (row + 1) * 6 - col;
    });
    for (const value of values) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.setAttribute('role', 'gridcell');
      cell.setAttribute('aria-label', `Square ${value}${value === 30 ? ', finish' : ''}`);
      if (value === 1) cell.classList.add('start');
      if (value === 30) cell.classList.add('goal');
      const number = document.createElement('span');
      number.className = 'cell-number';
      number.textContent = value;
      cell.append(number);
      if (ladders.has(value) || snakes.has(value)) {
        const marker = document.createElement('span');
        marker.className = `cell-mark ${ladders.has(value) ? 'ladder' : 'snake'}`;
        marker.setAttribute('aria-hidden', 'true');
        marker.textContent = ladders.has(value) ? '↗' : '〰';
        cell.append(marker);
      }
      if (position === value) {
        const token = document.createElement('span');
        token.className = 'token';
        token.setAttribute('aria-hidden', 'true');
        cell.append(token);
      }
      board.append(cell);
    }
  }
}

function roll() {
  if (finished) return;
  const result = Math.floor(Math.random() * 6) + 1;
  dieDisplay.textContent = result;
  dieDisplay.setAttribute('aria-label', `Die: ${result}`);
  const landing = position + result;
  if (landing > 30) {
    message.textContent = `Rolled ${result}; you need an exact roll to finish.`;
  } else {
    position = landing;
    if (ladders.has(position)) {
      const end = ladders.get(position);
      message.textContent = `Rolled ${result}; climbed from ${position} to ${end}!`;
      position = end;
    } else if (snakes.has(position)) {
      const end = snakes.get(position);
      message.textContent = `Rolled ${result}; slid from ${position} to ${end}.`;
      position = end;
    } else {
      message.textContent = position === 30 ? `Rolled ${result}; you made it!` : `Rolled ${result}; keep going!`;
    }
  }
  squareDisplay.textContent = position;
  renderBoard();
  if (position === 30) {
    finished = true;
    message.textContent = 'You reached 30. You win!';
    rollButton.disabled = true;
  }
}

rollButton.addEventListener('click', roll);
renderBoard();
